USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_WorkflowRule_GetAll @ActiveOnly BIT=1
AS BEGIN SET NOCOUNT ON; SELECT r.WORKFLOW_RULE_ID,r.RULE_CODE,r.RULE_NAME,r.ASSET_ID,a.ASSET_CODE,a.ASSET_NAME,r.REQ_TYPE,r.MIN_AMOUNT,r.MAX_AMOUNT,r.CONCERN_DIVISION_ID,s.SETUP_CODE,o.ORG_UNIT_NAME CONCERN_DIVISION_NAME,r.AUTHORITY_BEFORE_DIVISION,r.DESTINATION_AFTER_CONCERN,r.PRIORITY_ORDER,r.IS_ACTIVE,r.EFFECTIVE_FROM,r.EFFECTIVE_TO FROM dbo.WORKFLOW_RULE r JOIN dbo.ASSET_MASTER a ON a.ASSET_ID=r.ASSET_ID LEFT JOIN dbo.CONCERN_DIVISION_SETUP s ON s.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID LEFT JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=s.ORG_UNIT_ID WHERE @ActiveOnly=0 OR r.IS_ACTIVE=1 ORDER BY a.ASSET_NAME,r.REQ_TYPE,r.PRIORITY_ORDER,r.MIN_AMOUNT; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_WorkflowRule_GetById @WorkflowRuleId BIGINT
AS BEGIN SET NOCOUNT ON; SELECT r.WORKFLOW_RULE_ID,r.RULE_CODE,r.RULE_NAME,r.ASSET_ID,a.ASSET_CODE,a.ASSET_NAME,r.REQ_TYPE,r.MIN_AMOUNT,r.MAX_AMOUNT,r.CONCERN_DIVISION_ID,s.SETUP_CODE,o.ORG_UNIT_NAME CONCERN_DIVISION_NAME,r.AUTHORITY_BEFORE_DIVISION,r.DESTINATION_AFTER_CONCERN,r.PRIORITY_ORDER,r.IS_ACTIVE,r.EFFECTIVE_FROM,r.EFFECTIVE_TO FROM dbo.WORKFLOW_RULE r JOIN dbo.ASSET_MASTER a ON a.ASSET_ID=r.ASSET_ID LEFT JOIN dbo.CONCERN_DIVISION_SETUP s ON s.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID LEFT JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=s.ORG_UNIT_ID WHERE r.WORKFLOW_RULE_ID=@WorkflowRuleId; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_WorkflowRule_Evaluate @AssetId BIGINT,@ReqType VARCHAR(20),@Amount DECIMAL(18,2),@AsOfDate DATE=NULL
AS BEGIN SET NOCOUNT ON; SET @AsOfDate=COALESCE(@AsOfDate,CONVERT(DATE,SYSUTCDATETIME())); SELECT TOP(1) r.WORKFLOW_RULE_ID,r.RULE_CODE,r.RULE_NAME,r.ASSET_ID,a.ASSET_CODE,a.ASSET_NAME,r.REQ_TYPE,r.MIN_AMOUNT,r.MAX_AMOUNT,r.CONCERN_DIVISION_ID,s.SETUP_CODE,o.ORG_UNIT_NAME CONCERN_DIVISION_NAME,r.AUTHORITY_BEFORE_DIVISION,r.DESTINATION_AFTER_CONCERN,r.PRIORITY_ORDER,r.IS_ACTIVE,r.EFFECTIVE_FROM,r.EFFECTIVE_TO,CASE WHEN r.AUTHORITY_BEFORE_DIVISION=1 THEN 'PROCUREMENT_AUTHORITY' WHEN r.CONCERN_DIVISION_ID IS NOT NULL THEN 'CONCERN_DIVISION' ELSE r.DESTINATION_AFTER_CONCERN END CALCULATED_ROUTE FROM dbo.WORKFLOW_RULE r JOIN dbo.ASSET_MASTER a ON a.ASSET_ID=r.ASSET_ID LEFT JOIN dbo.CONCERN_DIVISION_SETUP s ON s.CONCERN_DIVISION_ID=r.CONCERN_DIVISION_ID LEFT JOIN dbo.ORG_UNIT o ON o.ORG_UNIT_ID=s.ORG_UNIT_ID WHERE r.ASSET_ID=@AssetId AND r.REQ_TYPE=@ReqType AND r.IS_ACTIVE=1 AND r.EFFECTIVE_FROM<=@AsOfDate AND (r.EFFECTIVE_TO IS NULL OR r.EFFECTIVE_TO>=@AsOfDate) AND (r.MIN_AMOUNT IS NULL OR @Amount>=r.MIN_AMOUNT) AND (r.MAX_AMOUNT IS NULL OR @Amount<=r.MAX_AMOUNT) ORDER BY r.PRIORITY_ORDER,CASE WHEN r.MIN_AMOUNT IS NULL THEN 1 ELSE 0 END,COALESCE(r.MAX_AMOUNT,9999999999999999)-COALESCE(r.MIN_AMOUNT,0),r.WORKFLOW_RULE_ID; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_WorkflowRule_SaveValidated @WorkflowRuleId BIGINT=NULL,@RuleCode VARCHAR(40),@RuleName NVARCHAR(200),@AssetId BIGINT,@ReqType VARCHAR(20),@MinAmount DECIMAL(18,2)=NULL,@MaxAmount DECIMAL(18,2)=NULL,@ConcernDivisionId BIGINT=NULL,@AuthorityBeforeDivision BIT=0,@DestinationAfterConcern VARCHAR(30),@PriorityOrder INT=100,@IsActive BIT=1,@EffectiveFrom DATE,@EffectiveTo DATE=NULL,@Actor VARCHAR(50)
AS BEGIN SET NOCOUNT ON; IF @WorkflowRuleId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.WORKFLOW_RULE WHERE WORKFLOW_RULE_ID=@WorkflowRuleId) BEGIN SELECT '002' RESULT_CODE,N'Workflow rule not found.' RESULT_MESSAGE,@WorkflowRuleId ENTITY_ID,@RuleCode REFERENCE_NO; RETURN; END; IF NOT EXISTS(SELECT 1 FROM dbo.ASSET_MASTER WHERE ASSET_ID=@AssetId AND IS_ACTIVE=1) BEGIN SELECT '001' RESULT_CODE,N'Asset is missing or inactive.' RESULT_MESSAGE,@WorkflowRuleId ENTITY_ID,@RuleCode REFERENCE_NO; RETURN; END; IF @ConcernDivisionId IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.CONCERN_DIVISION_SETUP WHERE CONCERN_DIVISION_ID=@ConcernDivisionId AND IS_ACTIVE=1) BEGIN SELECT '001' RESULT_CODE,N'Concern division is missing or inactive.' RESULT_MESSAGE,@WorkflowRuleId ENTITY_ID,@RuleCode REFERENCE_NO; RETURN; END; EXEC dbo.usp_WorkflowRule_Save @WorkflowRuleId,@RuleCode,@RuleName,@AssetId,@ReqType,@MinAmount,@MaxAmount,@ConcernDivisionId,@AuthorityBeforeDivision,@DestinationAfterConcern,@PriorityOrder,@IsActive,@EffectiveFrom,@EffectiveTo,@Actor; END;
GO
